//! The client of the job service, `jobscheduler.v1.JobService` (design section 3.6):
//! [`JobClient`], with one method per call of the definition, taking and returning the
//! messages of `js-proto`. The methods are generated by `cargo xtask gen-job-surface` from the
//! service's descriptor set (`generated.rs`), so a call added to the definition appears here
//! with no hand-written code; this module holds what is not about any call: the connection,
//! the token, and how a failure is classified ([`JobError`]).
//!
//! The connection keeps the rules of the lease client ([`crate::Client`]): the same
//! `--server` check ([`crate::ServerUrl::parse`]: `https://`, or `http://` for a loopback
//! host only, no user, path or query), the same owner-only token file
//! ([`crate::bearer`]), and for `https://` the certificates of `--ca-cert` only or, without
//! it, the public roots bundled in `webpki-roots`, never the platform's store. The channel
//! speaks gRPC to that one origin and nowhere else: it reads no proxy setting and follows no
//! redirect (gRPC has none; an HTTP redirect answer is an error). The bearer is sent as
//! `authorization` metadata on every call, marked sensitive so HTTP/2 never indexes it.

mod error;
mod generated;
mod wire;

use std::path::Path;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Duration;

use js_proto::v1::job_service_client::JobServiceClient;
use tonic::metadata::{Ascii, MetadataValue};
use tonic::transport::{Channel, Endpoint};

pub use error::{JobError, NotSent};
pub use wire::{Dialed, Dialer, Io};

use crate::server_url::ServerUrl;
use crate::token;

/// A client of the job service at one origin, holding one token. It never prints the token:
/// it has no `Debug`.
///
/// A call that fails says whether it may have taken effect ([`JobError::may_have_acted`]).
/// The client never retries and never changes a request: a caller that tries again sends
/// the same request.
#[derive(Clone)]
pub struct JobClient {
    service: JobServiceClient<Channel>,
    bearer: MetadataValue<Ascii>,
    base: String,
    /// How many requests the client's connections have begun to write.
    begun: Arc<AtomicU64>,
}

/// How many requests had begun to be written when a call started.
#[derive(Debug, Clone, Copy)]
struct Attempt(u64);

impl JobClient {
    /// Checks the flags and builds the client, as [`crate::Client::connect`] does: the URL,
    /// the owner-only token file and, for `https://`, the roots to trust. Every call is
    /// limited to `limit`, connecting included. Nothing is dialled until the first call.
    ///
    /// # Errors
    ///
    /// [`NotSent::Flag`] naming `--server`, `--token-file` or `--ca-cert` when that flag, or
    /// the file it names, is unusable.
    pub async fn connect(
        server: &str,
        token_file: &Path,
        ca_cert: Option<&Path>,
        limit: Duration,
    ) -> Result<Self, JobError> {
        Self::connect_via(server, token_file, ca_cert, limit, Dialer::tcp()).await
    }

    /// [`JobClient::connect`], opening its byte stream with `dialer` instead of TCP.
    ///
    /// # Errors
    ///
    /// As [`JobClient::connect`].
    pub async fn connect_via(
        server: &str,
        token_file: &Path,
        ca_cert: Option<&Path>,
        limit: Duration,
        dialer: Dialer,
    ) -> Result<Self, JobError> {
        let server = ServerUrl::parse(server)?;
        let bearer = token::bearer(token_file)?;
        let mut bearer = MetadataValue::try_from(bearer.as_str())
            .map_err(|why| JobError::flag("--token-file", why))?;
        bearer.set_sensitive(true);
        let begun = Arc::new(AtomicU64::new(0));
        let connector = wire::Connector::new(&server, ca_cert, dialer, Arc::clone(&begun))?;
        let endpoint = Endpoint::from_shared(server.base.clone())
            .map_err(|why| JobError::flag("--server", why))?
            .timeout(limit)
            .connect_timeout(limit);
        let channel = endpoint.connect_with_connector_lazy(connector);
        Ok(Self {
            service: JobServiceClient::new(channel),
            bearer,
            base: server.base,
            begun,
        })
    }

    /// The request of a call carrying `message` and the bearer, and the count of requests
    /// begun before it.
    fn begin<T>(&self, message: T) -> (Attempt, tonic::Request<T>) {
        let mut request = tonic::Request::new(message);
        request
            .metadata_mut()
            .insert("authorization", self.bearer.clone());
        (Attempt(self.begun.load(Ordering::SeqCst)), request)
    }

    /// The kind of failure `status` is for the call that began at `attempt`: the request
    /// was written when a request began after it.
    fn classify(&self, attempt: Attempt, status: &tonic::Status) -> JobError {
        let written = self.begun.load(Ordering::SeqCst) > attempt.0;
        error::classify(&self.base, written, status)
    }
}
